<?php
declare(strict_types=1);
require_once __DIR__.'/HospitalDirectory.php';
final class Installer {
 public static function install(string $name,string $email,string $password,bool $samples): void {
  if(mb_strlen($name)<2||mb_strlen($name)>100||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12||strlen($password)>72)throw new InvalidArgumentException('Use a valid name, email and a password of 12–72 characters.');
  $c=require dirname(__DIR__).'/config/database.php';if(!preg_match('/^[a-zA-Z0-9_]+$/',$c['database']))throw new InvalidArgumentException('Invalid database name.');
  $pdo=new PDO("mysql:host={$c['host']};port={$c['port']};charset=utf8mb4",$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
  $pdo->exec("SET time_zone='+05:30'");$check=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=?');$check->execute([$c['database']]);if($check->fetchColumn()>0)throw new RuntimeException('This database already contains tables. Setup will not overwrite an existing installation.');
  $sql=file_get_contents(dirname(__DIR__).'/database/schema.sql');$sql=str_replace('safenation_disaster_link',$c['database'],$sql);
  foreach(explode(';',$sql) as $statement)if(trim($statement)!=='')$pdo->exec($statement);
  $pdo->beginTransaction();try {
   $add=function(string $n,string $e,string $pw,string $role)use($pdo):int{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role,phone,area) VALUES(?,?,?,?,?,?)');$s->execute([$n,$e,password_hash($pw,PASSWORD_DEFAULT),$role,'','Kandy']);return (int)$pdo->lastInsertId();};
   $admin=$add($name,strtolower($email),$password,'admin');
   if($samples) {
    $demo='Demo@SafeNation2026';$authority=$add('Authority Coordinator','authority@example.test',$demo,'authority');$citizen=$add('Citizen User','citizen@example.test',$demo,'citizen');$volunteer=$add('Volunteer User','volunteer@example.test',$demo,'volunteer');$responder=$add('Response Team','responder@example.test',$demo,'responder');$manager=$add('Facility Manager','facility@example.test',$demo,'facility_manager');
    $exec=function(string $sql,array $args)use($pdo){$pdo->prepare($sql)->execute($args);};
    $exec('INSERT INTO volunteers(user_id,skills,experience,availability,service_area) VALUES(?,?,?,?,?)',[$volunteer,'First aid, logistics, translation','Example volunteer profile for first aid, logistics and translation.','available','Kandy']);
    $samples=[['Example incident: rising water near a community road',1,'Example record: floodwater has blocked access to homes. Several people need assistance.','Kandy',7.2906,80.6337,38,'moderate','High','verified'],['Example incident: slope movement after rain',2,'Example record: soil has moved beside a road after heavy rain. No injuries have been reported.','Nuwara Eliya',6.9497,80.7891,8,'moderate','High','verified'],['Example incident: local storm damage',3,'Example record: fallen branches have blocked a lane. Minor property damage has been reported.','Colombo',6.9271,79.8612,4,'minor','Low','verified'],['Example incident: building fire requiring urgent review',4,'Example record: fire has spread through a building. People are trapped and injured.','Matale',7.4675,80.6234,120,'severe','Critical','pending']];
    foreach($samples as $i=>$r){[$title,$type,$desc,$area,$lat,$lng,$people,$damage,$severity,$status]=$r;$names=[1=>'Flood',2=>'Landslide',3=>'Storm',4=>'Fire'];$ai=Severity::classify($names[$type],$desc,$people,$damage);$exec('INSERT INTO reports(user_id,type_id,title,description,area,latitude,longitude,occurred_at,affected_people,damage,ai_severity,ai_reason,severity,status,created_at) VALUES(?,?,?,?,?,?,?,DATE_SUB(NOW(),INTERVAL 2 HOUR),?,?,?,?,?,?,DATE_SUB(NOW(),INTERVAL ? DAY))',[$citizen,$type,$title,$desc,$area,$lat,$lng,$people,$damage,$ai['level'],$ai['reason'],$severity,$status,$i]);$id=(int)$pdo->lastInsertId();if($status==='verified')$exec('INSERT INTO report_reviews(report_id,reviewer_id,status,severity,note) VALUES(?,?,?,?,?)',[$id,$authority,'verified',$severity,'Reviewed as an example incident for project testing.']);}
    $exec('INSERT INTO alerts(author_id,type_id,title,message,area,severity,expires_at) VALUES(?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY))',[$authority,1,'Example alert: flood response update','Example alert for project testing. A flood response is being coordinated in this scenario. View the situation map and example facilities for details.','Kandy','High']);
    $fs=[['shelter','Kandy Community Shelter (example)','Kandy','Example location, Kandy (not a real facility address)',7.296,80.638,120,36,'Example services: drinking water, accessible entrance, sanitation','No real contact number',0,'open'],['hospital','Central Emergency Hospital (example)','Kandy','Example location, Kandy (not a real facility address)',7.281,80.62,60,28,'Example services: emergency care, first aid, accessible entrance','No real contact number',1,'open'],['shelter','Hill Country Shelter (example)','Nuwara Eliya','Example location, Nuwara Eliya (not a real facility address)',6.96,80.78,80,67,'Example services: beds, drinking water, sanitation','No real contact number',0,'limited'],['hospital','Colombo Care Centre (example)','Colombo','Example location, Colombo (not a real facility address)',6.92,79.87,100,45,'Example services: medical triage, emergency care','No real contact number',1,'open']];
    foreach($fs as $f)$exec('INSERT INTO facilities(manager_id,kind,name,area,address,latitude,longitude,capacity,occupancy,services,phone,emergency_service,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$manager,...$f]);
    foreach([['Drinking water','Water','litres','Kandy depot',800,200],['Family food packs','Food','packs','Kandy depot',140,50],['First-aid kits','Medicine','kits','Central depot',12,15],['Drinking water','Water','litres','Colombo depot',200,100]] as $r){$exec('INSERT INTO resources(name,category,unit,location,quantity,minimum_quantity) VALUES(?,?,?,?,?,?)',$r);$rid=(int)$pdo->lastInsertId();$exec('INSERT INTO resource_transactions(resource_id,user_id,kind,quantity,destination,note) VALUES(?,?,?,?,?,?)',[$rid,$admin,'received',$r[4],'Example opening stock','Example inventory for project testing']);}
    $exec("INSERT INTO assistance_requests(user_id,assigned_to,category,description,area,latitude,longitude,people,status,note) VALUES(?,?,?,?,?,?,?,?,?,?)",[$citizen,$responder,'Food and water','Example request: a family needs food and drinking water after a flood.','Kandy',7.29,80.63,5,'assigned','A response team has been assigned to this example request.']);
    $exec('INSERT INTO volunteer_assignments(volunteer_id,report_id,coordinator_id,title,instructions,area,due_at) VALUES(?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY))',[$volunteer,1,$authority,'Example assignment: coordinate shelter supplies','Example assignment for project testing. Check the example shelter inventory and contact the assigned coordinator.','Kandy']);
    foreach([$admin,$authority,$citizen,$volunteer,$responder,$manager] as $id)$exec('INSERT INTO notifications(user_id,title,message,link) VALUES(?,?,?,?)',[$id,'Welcome to SafeNation','Welcome to SafeNation. Use your dashboard to view reports, requests and assignments. Records marked as examples are for project testing.','index.php?page=dashboard']);
   }
   HospitalDirectory::seed($pdo);
   $pdo->prepare('INSERT INTO audit_logs(user_id,action,entity,entity_id,detail) VALUES(?,?,?,?,?)')->execute([$admin,'installation_completed','users',$admin,$samples?'Example records included':'Hospital directory enabled']);
   $pdo->commit();
  }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();throw $ex;}
 }
}
